INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl2x-42da62', '2026-10-29T22:10:00.441Z', 'Thomas Uriel FernÃ¡ndez', NULL, 'decision', NULL, 'Alcance prioritario del backoffice: descuentos, armado de combos y alertas', 'RevisiÃ³n del backoffice del 15/10: esos tres ejes alcanzan para justificar el sistema. Se pulen antes de sumar funcionalidades nuevas. Los pendientes [Producto] (lotes, mermas, conteo, tablero) van despuÃ©s.', 'backend/src/main/java/ar/com/coto/stock/service/ServicioValorizacion.java,backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/observer/AlertaStockBajo.java', NULL, NULL);
