INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl5s-83a1df', '2026-10-29T22:10:00.545Z', 'Thomas Uriel FernÃ¡ndez', NULL, 'pendiente', NULL, '[Alta] Armado y desarmado de combos con stock propio', 'Los combos hoy son virtuales (disponible calculado desde componentes, sin contadores). Mantener ese modelo (Composite) y agregar movimientos ARMADO/DESARMADO que pasan N unidades de los componentes al stock propio del combo y viceversa, para combos armados fÃ­sicamente (ej. canastas). Definir cÃ³mo conviven stock propio y disponible virtual, y quÃ© pasa con componentes compartidos.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/TipoMovimiento.java,backend/src/main/resources/schema.sql', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl76-6cab97', '2026-10-29T22:10:00.594Z', 'Thomas Uriel FernÃ¡ndez', NULL, 'pendiente', NULL, '[Alta] Documento funcional de los tres ejes: descuentos, combos y alertas', 'Explicar cada eje con su caso de uso, el patrÃ³n que lo resuelve (Decorator en ServicioValorizacion, Composite en ComboStock/LineaCombo, Observer + Strategy en AlertaStockBajo y notificadores), las decisiones tomadas y los lÃ­mites. Incluir cÃ³mo se maneja el stock de combos y responder: componentes compartidos entre combos y venta del artÃ­culo suelto que deja sin stock al combo.', 'docs/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3mvmx-75b422', '2026-10-29T22:12:34.090Z', 'Thomas Uriel FernÃ¡ndez', NULL, 'evento', NULL, 'Rama feature/backoffice-harness-design-system subida al repo', 'Commits: backend del backoffice, frontend + Design System, harness + memoria, documentaciÃ³n como producto COTO. Pendiente: PR a main.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3q1cd-bdafc3', '2026-10-29T22:15:01.453Z', 'Thomas Uriel FernÃ¡ndez', NULL, 'convencion', NULL, 'Commits y PRs sin atribuciÃ³n de IA', 'Los commits van a nombre de quien los hace. Nunca agregar Co-Authored-By de una IA ni ''Generated with Claude Code''. Cada integrante crea .claude/settings.local.json con attribution vacÃ­o (ver CLAUDE.md).', 'CLAUDE.md,.gitignore', NULL, NULL);
