INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4ckms-fc0dbd', '2026-10-29T22:32:32.884Z', 'Thomas Uriel FernÃ¡ndez', 'implementador', 'decision', NULL, 'MigraciÃ³n de estilos a la grilla de 8 con empates hacia arriba', 'padding/margin/gap se ajustan a mÃºltiplos de 8 (12â†’16, 20â†’24); 4 px â†’ --space-half; 1-3 px, posiciones, anchos y altos quedan literales. Nuevos tokens: --space-half, --radius-xs, --color-overlay, --color-overlay-soft. Sin desbordes en 9 vistas a 390 y 1280 px.', 'frontend/src/styles/app.css,frontend/src/styles/shell.css,frontend/src/styles/tokens.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4cko4-f27020', '2026-10-29T22:32:32.932Z', 'Thomas Uriel FernÃ¡ndez', 'implementador', 'decision', NULL, 'Swagger con springdoc 3.1.1', 'Se elige 3.1.1 (Boot 4.1.x) y no 3.2.0 por tener menos de dos semanas al momento de agregarla. Solo documenta /api/**; cada controller tiene @Tag. UI en /swagger-ui.html, spec en /v3/api-docs.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/config/ConfiguracionOpenApi.java', NULL, NULL);
