INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzjv0e8-10536c', '2026-11-02T17:45:38.242Z', 'Nicolas', NULL, 'decision', NULL, 'AutenticaciÃ³n JWT y roles de sucursal con patrones Adapter y Strategy', 'Se implementÃ³ Spring Security sin estado con tokens JWT, Adapter UsuarioSecurityAdapter para adaptar UsuarioEntity a UserDetails, Strategy BCryptPasswordEncoder y login en frontend con control de acceso por rol.', 'backend/pom.xml,backend/src/main/resources/schema.sql,backend/src/main/java/ar/com/coto/stock/adapter/UsuarioSecurityAdapter.java,backend/src/main/java/ar/com/coto/stock/config/ConfiguracionSeguridad.java,frontend/src/store.tsx,frontend/src/components/LoginScreen.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzps0r3-a4ffa8', '2026-11-02T20:31:16.433Z', 'Nicolas', NULL, 'decision', NULL, 'Armado y desarmado de combos con stock propio y Strategy', 'Soporte para combos con stock fisico propio manteniendo Composite. Se agregaron movimientos ARMADO_COMBO y DESARMADO_COMBO que transfieren unidades fisicas de componentes a stock propio del combo y viceversa. Convivencia de stock: disponibleTotal = disponiblePropio + disponibleVirtual. Patron Strategy EstrategiaReservaCombo con ReservaFisicoPrimero por defecto y ReservaVirtualPrimero como alternativa configurable. Endpoints REST POST /api/combos/{id}/armado y /desarmado accesibles por REPOSITOR y SUPERVISOR.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/EstrategiaReservaCombo.java,backend/src/main/java/ar/com/coto/stock/domain/model/ReservaFisicoPrimero.java,backend/src/main/java/ar/com/coto/stock/domain/model/ReservaVirtualPrimero.java,backend/src/main/java/ar/com/coto/stock/controller/ComboController.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzq0stb-f24110', '2026-11-02T20:38:06.049Z', 'Nicolas', NULL, 'decision', NULL, 'Documento funcional de los tres ejes: descuentos, combos y alertas', 'Especificacion funcional y tecnica de los tres ejes del backoffice: Descuentos con Decorator en ServicioValorizacion y acumulacion determinista; Combos con Composite en ComboStock/StockSimple y Strategy en EstrategiaReservaCombo, documentando convivencia de stock propio con disponible virtual, componentes compartidos y proteccion ante venta suelta; Alertas con Observer en AlertaStockBajo y Strategy en ServicioNotificaciones con resolucion jerarquica articulo->categoria->sucursal y outbox transaccional.', 'docs/tres-ejes-funcionales.md,README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw01e-01', '2026-11-03T12:05:00.000Z', 'Juan Pablo', 'lider', 'decision', 'destinatarios-avisos-emails', 'Destinatarios de avisos como listas de emails con resolución jerárquica y outbox múltiple', 'Separación de destinatarios de la política de reposición. Gestión de emails en Configuración (general y categoría). Resolución jerárquica (categoría si tiene, sino general). EventoIntegracion ALERTA canal EMAIL por cada dirección con clave outbox única. PolicyForm simplificado.', 'backend/src/main/resources/db/upgrade-destinatarios-avisos.sql,backend/src/main/java/ar/com/coto/stock/service/ServicioDestinatarios.java,frontend/src/pages/NoticeRecipients.tsx,frontend/src/components/CatalogForms.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw01e-02', '2026-11-03T12:05:01.000Z', 'Juan Pablo', 'lider', 'evento', 'destinatarios-avisos-emails', 'Tarea de destinatarios de avisos como listas de emails completada y aprobada por el harness', '9 criterios de aceptación cumplidos, suites automatizadas y auditoría de UI del Design System COTO aprobadas.', '.claude/work/destinatarios-avisos-emails/', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqgr-504925', '2026-10-29T21:49:54.363Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'El proyecto se presenta como un desarrollo de COTO', 'Ningún archivo nuevo menciona la universidad, el trabajo práctico ni la materia. Textos, código y documentación se escriben como un producto interno de COTO.', 'CLAUDE.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqi9-67bd33', '2026-10-29T21:49:54.417Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'Memoria compartida obligatoria', 'Toda IA del equipo lee ''contexto'' al empezar y registra decisiones, aprendizajes, pendientes y eventos al terminar. .claude/memoria/ va en el mismo commit que el cambio.', '.claude/memoria/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqjo-1852e1', '2026-10-29T21:49:54.468Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'Flujo /equipo con cinco agentes', 'lider → disenador-ux-ui (si hay UI) → implementador → tester + reviewer + auditoría en paralelo → correcciones (máx. 3) → cierre del lider. Artefactos en .claude/work/<slug>/.', '.claude/skills/equipo/SKILL.md,docs/harness-engineering.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqkz-4f19e4', '2026-10-29T21:49:54.515Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Tokens del Design System alineados a las Foundations de COTO', 'Se corrigieron 15 colores que diferían de las láminas. --info-900 pasó a --info-800. Se agregaron espaciado de 8 pt, grilla 1024/9 columnas, roles semánticos y components.css con los átomos.', 'frontend/src/styles/tokens.css,frontend/src/styles/components.css,docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqmc-64bcd0', '2026-10-29T21:49:54.565Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Primary 700 = #A41908 (la lámina dice #041988)', '#041988 es azul y no coincide con la muestra roja. Se conserva #A41908 (contraste 7.72:1; la lámina indica 8.88). Confirmar con diseño.', 'frontend/src/styles/tokens.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqnn-2fa518', '2026-10-29T21:49:54.611Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Botón Warning con texto oscuro', 'Texto blanco sobre #DDAD00 da 2:1 y no cumple AA. Se usa Neutral 900.', 'frontend/src/styles/components.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqp1-c500bd', '2026-10-29T21:49:54.661Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Íconos con lucide-react en lugar de Untitled UI', 'Misma base Feather, outline y trazo redondeado; evita una dependencia nueva. Tamaños 24/32/48.', 'docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqqh-e1828c', '2026-10-29T21:49:54.713Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', NULL, 'components.css se importa antes de app.css', 'Las reglas de cada vista (anchos de botón en móvil, etc.) deben poder pisar a los átomos con la misma especificidad.', 'frontend/src/main.tsx', NULL, NULL);
