INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqpr-80a2c9', '2026-10-29T22:03:07.840Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Autenticación y roles de sucursal', 'No hay Spring Security; el usuario de movimientos llega como texto en el body. Login con roles (Recepción, Repositor, Compras, Supervisor), usuario tomado del token y permisos por acción.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/dto/Solicitudes.java,backend/src/main/java/ar/com/coto/stock/config/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqr7-eadc56', '2026-10-29T22:03:07.891Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Frontend recarga todo cada 20 s y hace N+1 de políticas', 'store.tsx pide todo cada 20 s y una política por artículo simple. Crear GET /api/politicas, paginar /movimientos y /auditoria, y recargar solo lo afectado por cada operación.', 'frontend/src/store.tsx,frontend/src/api.ts,backend/src/main/java/ar/com/coto/stock/controller/MovimientoController.java,backend/src/main/java/ar/com/coto/stock/controller/ReposicionController.java', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqsn-446388', '2026-10-29T22:03:07.943Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Pruebas automatizadas de frontend', 'No hay suite. Vitest + Testing Library para store, formularios y modales; Playwright para 2-3 recorridos críticos (reservar, recibir pedido).', 'frontend/package.json,frontend/src/store.tsx', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqu2-f13c57', '2026-10-29T22:03:07.995Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Validar contra PostgreSQL real con Testcontainers', 'El perfil postgres nunca se ejecutó contra un servidor real; solo H2 en modo PostgreSQL.', 'backend/src/test/java/ar/com/coto/stock/persistence/,backend/src/main/resources/application-postgres.properties', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqvh-e1c662', '2026-10-29T22:03:08.045Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Migrar app.css y shell.css a tokens del Design System', 'Quedan ~40 colores sueltos, ~105 font-size en px y ~226 espaciados fuera de la grilla de 8. Auditoría del disenador-ux-ui y migración vista por vista.', 'frontend/src/styles/app.css,frontend/src/styles/shell.css', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqwv-0e2e09', '2026-10-29T22:03:08.095Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Documentar la API con OpenAPI/Swagger (springdoc)', '47 operaciones documentadas solo en markdown y Postman.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/controller/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqy8-aa1095', '2026-10-29T22:03:08.144Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Lotes y vencimientos con salida FEFO', 'Para lácteos, fiambres y carnes: lote, fecha de vencimiento, alerta de próximo a vencer y salida primero-vence-primero-sale.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqzj-a34609', '2026-10-29T22:03:08.191Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Mermas y roturas como movimiento propio', 'Tipo de movimiento con motivo obligatorio y reporte, separado de los ajustes.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3ar0v-61c350', '2026-10-29T22:03:08.239Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Inventario cíclico (conteo de góndola)', 'Contar, comparar contra el sistema y generar ajuste aprobado por supervisor. Usar el Keypad del Design System para tablet/PDA.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3ar27-4bd7bb', '2026-10-29T22:03:08.287Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Tablero de indicadores de stock', 'Quiebres de stock, rotación y días de cobertura por categoría.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl2x-42da62', '2026-10-29T22:10:00.441Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Alcance prioritario del backoffice: descuentos, armado de combos y alertas', 'Revisión del backoffice del 15/10: esos tres ejes alcanzan para justificar el sistema. Se pulen antes de sumar funcionalidades nuevas. Los pendientes [Producto] (lotes, mermas, conteo, tablero) van después.', 'backend/src/main/java/ar/com/coto/stock/service/ServicioValorizacion.java,backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/observer/AlertaStockBajo.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl4d-004617', '2026-10-29T22:10:00.493Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Destinatarios de avisos como listas de emails, fuera de la política de reposición', 'Hoy el modal de Compras → Reposición → Política define reposición y también un único contacto/canal por artículo. Separar: nueva sección Configuración → Destinatarios de avisos con listas de emails por categoría y una lista general; el modal de política queda solo con parámetros de reposición; AlertaStockBajo envía un mail por cada dirección. Evaluar dejar SMS/WhatsApp en segundo plano. Requiere migración db/upgrade-*.sql.', 'backend/src/main/java/ar/com/coto/stock/domain/reposicion/PoliticaReposicion.java,backend/src/main/java/ar/com/coto/stock/service/ServicioContactos.java,frontend/src/pages/Purchases.tsx,frontend/src/pages/Settings.tsx', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl5s-83a1df', '2026-10-29T22:10:00.545Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Armado y desarmado de combos con stock propio', 'Los combos hoy son virtuales (disponible calculado desde componentes, sin contadores). Mantener ese modelo (Composite) y agregar movimientos ARMADO/DESARMADO que pasan N unidades de los componentes al stock propio del combo y viceversa, para combos armados físicamente (ej. canastas). Definir cómo conviven stock propio y disponible virtual, y qué pasa con componentes compartidos.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/TipoMovimiento.java,backend/src/main/resources/schema.sql', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl76-6cab97', '2026-10-29T22:10:00.594Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Documento funcional de los tres ejes: descuentos, combos y alertas', 'Explicar cada eje con su caso de uso, el patrón que lo resuelve (Decorator en ServicioValorizacion, Composite en ComboStock/LineaCombo, Observer + Strategy en AlertaStockBajo y notificadores), las decisiones tomadas y los límites. Incluir cómo se maneja el stock de combos y responder: componentes compartidos entre combos y venta del artículo suelto que deja sin stock al combo.', 'docs/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3mvmx-75b422', '2026-10-29T22:12:34.090Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Rama feature/backoffice-harness-design-system subida al repo', 'Commits: backend del backoffice, frontend + Design System, harness + memoria, documentación como producto COTO. Pendiente: PR a main.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3q1cd-bdafc3', '2026-10-29T22:15:01.453Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'Commits y PRs sin atribución de IA', 'Los commits van a nombre de quien los hace. Nunca agregar Co-Authored-By de una IA ni ''Generated with Claude Code''. Cada integrante crea .claude/settings.local.json con attribution vacío (ver CLAUDE.md).', 'CLAUDE.md,.gitignore', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu45g2x-345e11', '2026-10-29T22:27:00.393Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Thomas toma: migrar estilos a tokens y documentar la API con Swagger', 'Reparto de tareas del equipo. Pendientes mvu3aqvh-e1c662 y mvu3aqwv-0e2e09 en curso.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4ckms-fc0dbd', '2026-10-29T22:32:32.884Z', 'Thomas Uriel Fernández', 'implementador', 'decision', NULL, 'Migración de estilos a la grilla de 8 con empates hacia arriba', 'padding/margin/gap se ajustan a múltiplos de 8 (12→16, 20→24); 4 px → --space-half; 1-3 px, posiciones, anchos y altos quedan literales. Nuevos tokens: --space-half, --radius-xs, --color-overlay, --color-overlay-soft. Sin desbordes en 9 vistas a 390 y 1280 px.', 'frontend/src/styles/app.css,frontend/src/styles/shell.css,frontend/src/styles/tokens.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4cko4-f27020', '2026-10-29T22:32:32.932Z', 'Thomas Uriel Fernández', 'implementador', 'decision', NULL, 'Swagger con springdoc 3.1.1', 'Se elige 3.1.1 (Boot 4.1.x) y no 3.2.0 por tener menos de dos semanas al momento de agregarla. Solo documenta /api/**; cada controller tiene @Tag. UI en /swagger-ui.html, spec en /v3/api-docs.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/config/ConfiguracionOpenApi.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4ckph-6aaa5a', '2026-10-29T22:32:32.981Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Tareas de estilos a tokens y Swagger terminadas', 'Rama feature/tokens-y-swagger. 155 pruebas en verde, build del frontend OK.', 'frontend/src/styles/,backend/', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4i26u-8ed36b', '2026-10-29T22:36:48.918Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'PR #2 abierto: estilos a tokens y Swagger', 'https://github.com/thomyfernandez/sistema-gestion-stock-coto/pull/2 (feature/tokens-y-swagger → main). La rama del backoffice ya se mergeó como PR #1.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzjv0e8-10536c', '2026-11-02T17:45:38.242Z', 'Nicolas', NULL, 'decision', NULL, 'Autenticación JWT y roles de sucursal con patrones Adapter y Strategy', 'Se implementó Spring Security sin estado con tokens JWT, Adapter UsuarioSecurityAdapter para adaptar UsuarioEntity a UserDetails, Strategy BCryptPasswordEncoder y login en frontend con control de acceso por rol.', 'backend/pom.xml,backend/src/main/resources/schema.sql,backend/src/main/java/ar/com/coto/stock/adapter/UsuarioSecurityAdapter.java,backend/src/main/java/ar/com/coto/stock/config/ConfiguracionSeguridad.java,frontend/src/store.tsx,frontend/src/components/LoginScreen.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzps0r3-a4ffa8', '2026-11-02T20:31:16.433Z', 'Nicolas', NULL, 'decision', NULL, 'Armado y desarmado de combos con stock propio y Strategy', 'Soporte para combos con stock fisico propio manteniendo Composite. Se agregaron movimientos ARMADO_COMBO y DESARMADO_COMBO que transfieren unidades fisicas de componentes a stock propio del combo y viceversa. Convivencia de stock: disponibleTotal = disponiblePropio + disponibleVirtual. Patron Strategy EstrategiaReservaCombo con ReservaFisicoPrimero por defecto y ReservaVirtualPrimero como alternativa configurable. Endpoints REST POST /api/combos/{id}/armado y /desarmado accesibles por REPOSITOR y SUPERVISOR.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/EstrategiaReservaCombo.java,backend/src/main/java/ar/com/coto/stock/domain/model/ReservaFisicoPrimero.java,backend/src/main/java/ar/com/coto/stock/domain/model/ReservaVirtualPrimero.java,backend/src/main/java/ar/com/coto/stock/controller/ComboController.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzq0stb-f24110', '2026-11-02T20:38:06.049Z', 'Nicolas', NULL, 'decision', NULL, 'Documento funcional de los tres ejes: descuentos, combos y alertas', 'Especificacion funcional y tecnica de los tres ejes del backoffice: Descuentos con Decorator en ServicioValorizacion y acumulacion determinista; Combos con Composite en ComboStock/StockSimple y Strategy en EstrategiaReservaCombo, documentando convivencia de stock propio con disponible virtual, componentes compartidos y proteccion ante venta suelta; Alertas con Observer en AlertaStockBajo y Strategy en ServicioNotificaciones con resolucion jerarquica articulo->categoria->sucursal y outbox transaccional.', 'docs/tres-ejes-funcionales.md,README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmytu-57c26c', '2026-11-03T14:11:06.066Z', 'matisolivella', NULL, 'decision', NULL, 'Avisos por listas de emails, fuera del modal de política', 'Tabla destinatario_aviso (categoria_id nulo = lista general), hasta 20 emails normalizados. Resolución: lista de la categoría -> lista general -> respaldo anterior (contacto del artículo, de la categoría y configuracion_avisos con SMS/WhatsApp). Un evento de outbox por dirección. El modal de política sólo tiene reposición y umbral; conserva contactoId/canalAlerta existentes sin editarlos. Migración idempotente upgrade-destinatarios.sql, sin copiar datos.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ListaDestinatarios.java,backend/src/main/java/ar/com/coto/stock/service/ServicioContactos.java,backend/src/main/resources/db/upgrade-destinatarios.sql,frontend/src/pages/Settings.tsx,docs/destinatarios-de-avisos.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmyx9-2fbde1', '2026-11-03T14:11:06.189Z', 'matisolivella', NULL, 'decision', NULL, 'Frontend: recarga por grupos, sondeo liviano e historial paginado', 'GET /api/politicas reemplaza el N+1. /movimientos y /auditoria aceptan limite/pagina (y tipo) con X-Total-Count, del más reciente al más antiguo; sin limite mantienen la respuesta anterior. store.tsx: grupos inventario/politicas/configuracion; run(accion, mensaje, grupos) recarga sólo esos; sondeo de 20 s sólo productos+pedidos, pausado con pestaña oculta; revision avanza en el sondeo sólo si cambió el inventario.', 'frontend/src/store.tsx,frontend/src/api.ts,backend/src/main/java/ar/com/coto/stock/controller/MovimientoController.java,docs/rendimiento-y-pruebas.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmz0z-ebbc3a', '2026-11-03T14:11:06.323Z', 'matisolivella', NULL, 'decision', NULL, 'Pruebas: Vitest + Testing Library, Playwright y PostgreSQL real con Testcontainers', 'npm test (28 pruebas, backend simulado en src/test/backend.ts). npm run test:e2e: 3 recorridos contra el JAR en 18080 y Vite en 5174. PostgresRealTest con postgres:17-alpine (Testcontainers 2.0.5 del BOM de Boot), se omite sin Docker; incluye concurrencia con FOR UPDATE y migraciones desde v0.1. Backend: 190 pruebas en verde.', 'frontend/vitest.config.ts,frontend/playwright.config.ts,frontend/e2e/recorridos.spec.ts,backend/src/test/java/ar/com/coto/stock/persistence/PostgresRealTest.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmz4i-8269a9', '2026-11-03T14:11:06.451Z', 'matisolivella', NULL, 'aprendizaje', NULL, 'En Windows, mvn necesita JAVA_HOME a un JDK 21+', 'Con JAVA_HOME en JDK 17 la compilación falla con ''release version 21 not supported''. Docker Desktop debe estar iniciado para que PostgresRealTest no se omita.', 'backend/pom.xml', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmz83-3a3ed1', '2026-11-03T14:11:06.580Z', 'matisolivella', NULL, 'evento', NULL, 'Avisos por listas, rendimiento del frontend, pruebas de frontend y PostgreSQL real implementados', 'Rama feature/avisos-rendimiento-pruebas, sin commit. Los pendientes [Producto] (lotes, mermas, conteo, tablero) siguen abiertos para después.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rx6oa-f34810', '2026-11-03T14:19:02.794Z', 'matisolivella', NULL, 'evento', NULL, 'PR #5 abierto: avisos por listas, rendimiento, pruebas de frontend y PostgreSQL real', 'https://github.com/thomyfernandez/sistema-gestion-stock-coto/pull/5 hacia develop.', NULL, NULL, NULL);
